// ---------------------------------------------------------------------------------------------------- placeOrder: POST /api/v1/trading/orders
export type PlaceOrderBody = {
  /** paper = simulated, live = a venue or on-chain account. The two are never merged in one figure. */
  mode: "paper" | "live";
  /** paper account or venue account; required when the wallet has several on the venue — pattern: ^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$ */
  accountId?: string;
  /** `venue:symbol` (e.g. `hyperliquid:BTC`, `spot:ETH`); a bare symbol is accepted when it is not ambiguous */
  instrument: string;
  side: "buy" | "sell";
  type: "limit" | "market" | "stop_market" | "stop_limit" | "take_profit_market" | "take_profit_limit";
  /** quantity of the base asset. Exactly one of `size` and `notional` is required — pattern: ^\d+(\.\d+)?$ */
  size?: string;
  /** value of the order in the quote currency of the instrument (USD or a USD stablecoin on every venue of this wallet). The SERVER turns it into a size: notional / reference price, rounded DOWN to the lot size — the reference is the limit price, else the trigger price, else the mark price read now (503 `stale_data` when it is stale; 422 `below_min_size` under one lot). The answer carries the size that was used. Exactly one of `size` and `notional` is required. A SPOT order: a SELL names `size` (the quantity sold); a BUY names `notional` — the amount of the quote asset to spend — because a swap is exact-input — pattern: ^\d+(\.\d+)?$ */
  notional?: string;
  /** decimal number as a string (never a float) — pattern: ^\d+(\.\d+)?$ */
  price?: string;
  /** decimal number as a string (never a float) — pattern: ^\d+(\.\d+)?$ */
  triggerPrice?: string;
  /** default: false */
  reduceOnly?: boolean;
  /** default: "gtc" */
  tif?: "gtc" | "ioc" | "alo";
  slippageBps?: number;
  /** paper only: leverage setting of the instrument on the account. On a venue account the leverage is a venue setting — pattern: ^\d+(\.\d+)?$ */
  leverage?: string;
  /** highest fee accepted, USD; default: 10 bps of the notional — pattern: ^\d+(\.\d+)?$ */
  maxFeeUsd?: string;
  /** idempotency key of the ORDER; default: the Idempotency-Key header. The order id is derived from it and from the principal — pattern: ^[A-Za-z0-9._:-]{8,100}$ */
  clientOrderId?: string;
};
export type PlaceOrderResponse = {
  order: Order;
  /** true: this Idempotency-Key (or clientOrderId) already placed this order; nothing was sent again */
  idempotent: boolean;
  /** set while an owner order waits AWAITING_APPROVAL: where the owner approves it with the passkey. Always null for an API key */
  approval: {
    by: string;
    engine: string;
    accountId: string;
    clientId: string;
    hash: string | null;
    expiresAt: number | null;
    approve: {
      method: string;
      path: string;
      [extra: string]: unknown;
    };
    [extra: string]: unknown;
  } | null;
  [extra: string]: unknown;
};

